-- ═════════════════════════════════════════════════════════════════════════════
-- FORMULACIÓN 2027: carga los indicadores del año 2027 de los cinco archivos "2027FOR-DE-144 L1…L5" en el formulario del Plan de Acción 2027.
--   · 208 indicadores (las filas de 2027 de la hoja FORMULACIÓN de cada línea, L1 a L5) con su meta y su línea base.
--   · Su distribución por facultades (hoja FORMULACIÓN Y SEG. FACULTADES, valor de la VIGENCIA 2027): 307 filas.
--   · Solo formulación: el seguimiento queda vacío.
--
-- Cómo usarlo:
--   1. Haz un respaldo de la base de datos.
--   2. Ejecuta TODO el archivo de una vez (usa variables @).
--   3. El formulario se busca como el de año 2027 (tabla formularios, columna anio). Si ya tiene indicadores, NO carga nada (evita duplicar)
--      y lo avisa en el primer SELECT.
--   4. @ef = estado de la formulación:  0 = BORRADORES (la formulación está en primera etapa: se revisan y se publican en el sistema) ← por defecto;
--                                       2 = PUBLICADOS (aparecen directamente en Seguimiento).
--   5. Línea, motor, proyecto y objetivo salen del catálogo buscándolos por CÓDIGO (L1, M1, P1). Las dependencias, con el nombre de la tabla cargos.
--      Las facultades se buscan por nombre en la tabla facultades.
-- ═════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;
SET @ef = 0;
SET @anio = 2027;
SET @formulario = (SELECT id FROM formularios WHERE anio = 2027 ORDER BY id DESC LIMIT 1);
SET @ya = (SELECT COUNT(*) FROM formulacion_144 WHERE formulario_id = @formulario);
SET @base = (SELECT COALESCE(MAX(id), 0) FROM formulacion_144);
SELECT @formulario AS formulario_id, (SELECT titulo FROM formularios WHERE id = @formulario) AS titulo, @ya AS indicadores_que_ya_tenia,
       IF(@formulario IS NULL, 'NO EXISTE el formulario de 2027: créalo primero', IF(@ya = 0, 'Todo en orden: se cargará la formulación', 'NO SE CARGA NADA: el formulario ya tiene indicadores')) AS mensaje;

-- Tabla de apoyo: nombre EXACTO del catálogo (por código L1-M1-P1) para línea, objetivo, motor y proyecto. Si un código no existe se usa el texto del Excel.
DROP TABLE IF EXISTS tmp_lmp_2027;
CREATE TABLE tmp_lmp_2027 (lc VARCHAR(10), mc VARCHAR(10), pc VARCHAR(10), linea VARCHAR(500), objetivo TEXT, motor VARCHAR(500), proyecto VARCHAR(600)) DEFAULT CHARSET=utf8mb4;

-- Revisa qué nombre quedó para cada código (si alguno salió del Excel es que no estaba en el catálogo):
SELECT t.lc, t.mc, t.pc, t.linea, t.motor, t.proyecto FROM tmp_lmp_2027 t ORDER BY t.lc, t.mc, t.pc;

-- Formulación (primero a una tabla temporal; solo pasa a formulacion_144 si el formulario estaba vacío)
DROP TABLE IF EXISTS tmp_form_2027;
CREATE TABLE tmp_form_2027 LIKE formulacion_144;

START TRANSACTION;
SELECT id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, meta_resultado, proyecto, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por FROM tmp_form_2027 WHERE @ya = 0 AND @formulario IS NOT NULL;

-- Distribución por facultades (valor de la vigencia 2027). La facultad se busca por nombre.
DROP TABLE IF EXISTS tmp_fac_2027;
CREATE TABLE tmp_fac_2027 (n INT, facultad VARCHAR(60), dist DECIMAL(14,2)) DEFAULT CHARSET=utf8mb4;

SELECT @base + g.n, (SELECT fa.id FROM facultades fa WHERE fa.nombre LIKE CONCAT('%', g.facultad, '%') ORDER BY fa.id LIMIT 1), '', g.dist
FROM tmp_fac_2027 g
WHERE @ya = 0 AND @formulario IS NOT NULL AND (SELECT fa.id FROM facultades fa WHERE fa.nombre LIKE CONCAT('%', g.facultad, '%') ORDER BY fa.id LIMIT 1) IS NOT NULL
ON DUPLICATE KEY UPDATE distribucion = VALUES(distribucion);
COMMIT;

DROP TABLE IF EXISTS tmp_lmp_2027;
DROP TABLE IF EXISTS tmp_form_2027;
DROP TABLE IF EXISTS tmp_fac_2027;

-- Verificación (debe dar 208 indicadores):
SELECT COUNT(*) AS indicadores_2027 FROM formulacion_144 WHERE formulario_id = @formulario;
